	assert.equal(await client.activeBranchId(WORKSPACE_ID), "main");
	assert.equal(authorizationChecks, 2);
	assert.deepEqual(
		requests.map((request) => new URL(request.url).pathname),
		[
			`/workspaces/${WORKSPACE_ID}/lix/v1/`,
			`/workspaces/${WORKSPACE_ID}/lix/v1/`,
		],
	);
