				acquisitions += 1;
				return {
					startAndWaitForPorts: async () => {
						if (acquisitions === 1) {
							throw new Error(
								"Internal error in Durable Object storage caused object to be reset; reference = retry-me",
							);
						}
					},
					fetch: branchProtocolResponse,
				};
			},
		}),
		{ userId: "user-1", token: "secret-oauth-token" },
