		path: string,
	): Promise<{
		content: string;
		size: number;
		changeId: string;
		updatedAt: string;
	}> {
		const result = await this.client.execute(workspaceId, {
			sql: "SELECT data, lixcol_change_id, lixcol_updated_at FROM lix_file WHERE path = $1",
