export function containerErrorDetails(
	caught: unknown,
): Record<string, unknown> {
	return containerErrorDetailsWithSeen(caught, new Set());
}

function containerErrorDetailsWithSeen(
	caught: unknown,
	seen: Set<unknown>,
): Record<string, unknown> {
	if (!isObject(caught)) return { value: String(caught) };
