export function containerRetryDelayMs(
	retryCount: number,
	random: () => number = Math.random,
): number {
	const exponent = Math.min(Math.max(retryCount - 1, 0), 3);
	const ceiling = Math.min(
		MAX_RETRY_DELAY_MS,
		BASE_RETRY_DELAY_MS * 2 ** exponent,
