async function waitBeforeContainerRetry(
	options: FetchContainerWithRetryOptions,
	error: unknown,
	retryCount: number,
	retryDelay: ContainerRetryDelay,
	retryRandom: () => number,
): Promise<void> {
	const retryDelayMs = containerRetryDelayMs(retryCount, retryRandom);
	options.onRetry?.({
