function waitForPromiseWithAbort<T>(
	promise: Promise<T>,
	signal?: AbortSignal,
): Promise<T> {
	if (!signal) return promise;
	throwIfAborted(signal);
	return new Promise<T>((resolve, reject) => {
		let settled = false;
		const cleanup = () => signal.removeEventListener("abort", onAbort);
		const onFulfilled = (value: T) => {
			if (settled) return;
			settled = true;
			cleanup();
			resolve(value);
		};
		const onRejected = (error: unknown) => {
			if (settled) return;
			settled = true;
			cleanup();
			reject(
				error instanceof Error
					? error
					: new Error("Container operation failed.", { cause: error }),
			);
		};
		const onAbort = () => onRejected(abortReason(signal));
		signal.addEventListener("abort", onAbort, { once: true });
		promise.then(onFulfilled, onRejected);
	});
}

function abortReason(signal: AbortSignal): Error {
	return signal.reason instanceof Error
		? signal.reason
		: new DOMException("Container request was cancelled.", "AbortError");
}

function delay(milliseconds: number, signal?: AbortSignal): Promise<void> {
	return new Promise((resolve, reject) => {
		if (signal?.aborted) {
			reject(abortReason(signal));
			return;
		}
		const onAbort = () => {
			clearTimeout(timeout);
			reject(
				signal
					? abortReason(signal)
					: new DOMException("Container request was cancelled.", "AbortError"),
			);
		};
		const timeout = setTimeout(() => {
			signal?.removeEventListener("abort", onAbort);
			resolve();
		}, milliseconds);
		signal?.addEventListener("abort", onAbort, { once: true });
	});
}
